// v58: báo cáo năm trên điện thoại – thẻ tổng + thanh 3 phần + 1 biểu đồ cột (m³ | doanh thu) + bảng tháng thu gọn
const BCN_PHAN = [['Tiền nước', 'tienNuoc', '#1e88e5'], ['Thuế VAT', 'vat', '#43a047'], ['Phí nước thải', 'bvmt', '#fb8c00']];
function bcnDT(r) {
  const T = r.tong, tong = T.tong || 0, co = r.thangs.filter(t => t.coSo);
  const pt = v => tong ? v / tong * 100 : 0, ptS = v => pt(v).toFixed(1).replace('.', ',') + '%';
  const the = t => !t.coSo ? `<div class="bcn-th rong"><div class="d"><b>${esc(t.thang)}</b><span>chưa có số liệu</span></div></div>`
    : `<div class="bcn-th"><div class="d"><b>${esc(t.thang)}</b><span>${so(t.soHo)} hộ</span></div>
      <div class="r"><span>Sản lượng</span><b>${so(t.m3)} m³</b></div>
      ${r.khus.length > 1 ? `<div class="r khu">${r.khus.map(k => `<span>${esc(k)} <b>${t.khu[k] ? so(t.khu[k].m3) : '–'}</b></span>`).join('')}</div>` : ''}
      ${BCN_PHAN.map(p => `<div class="r"><span><i style="background:${p[2]}"></i>${p[0]}</span><b>${tien(t[p[1]])}</b></div>`).join('')}
      <div class="r tong"><span>Doanh thu</span><b>${tien(t.tong)}</b></div></div>`;
  return `<div class="bcn-dt">
    <div class="bcn-hero"><span class="nhan-h">Doanh thu năm ${esc(r.nam)}</span><b class="so-h">${tien(tong)}</b><small>${so(T.soThang)} tháng có số liệu · tiền phải thu theo chỉ số chốt</small>
      <div class="bcn-3-thanh" role="img" aria-label="Cơ cấu doanh thu">${BCN_PHAN.map(p => `<i style="width:${pt(T[p[1]]).toFixed(2)}%;background:${p[2]}"></i>`).join('')}</div>
      <ul class="bcn-3">${BCN_PHAN.map(p => `<li><i style="background:${p[2]}"></i><span>${p[0]}</span><b>${tien(T[p[1]])}</b><em>${ptS(T[p[1]])}</em></li>`).join('')}</ul></div>
    <div class="bcn-2">
      <div class="o"><span>Sản lượng năm</span><b>${so(T.m3)} m³</b><small>qua đồng hồ hộ dân</small></div>
      <div class="o"><span>Bình quân tháng</span><b>${co.length ? tien(Math.round(tong / co.length)) : '–'}</b><small>${co.length ? so(Math.round(T.m3 / co.length)) + ' m³/tháng' : '–'}</small></div></div>
    <div class="the bcn-bd"><div class="bcn-bd-dau"><h3>${ic('chart')} Từng tháng</h3><div class="bcn-chon" role="tablist" aria-label="Chọn số liệu"><button type="button" role="tab" data-bd="m3" class="on" aria-selected="true">m³</button><button type="button" role="tab" data-bd="tien" aria-selected="false">Doanh thu</button></div></div>
      <div id="bcnSVG"></div><div class="bcn-chi" id="bcnChi" aria-live="polite"></div><div class="nho bcn-goi">Bấm vào cột để xem số của tháng đó.</div></div>
    <div class="the bcn-bang-the"><button type="button" class="nut phu bcn-mo" id="bcnMoBang" aria-expanded="false" aria-controls="bcnBang">Xem bảng từng tháng</button>
      <div id="bcnBang" class="an">${r.thangs.map(the).join('')}
        <div class="bcn-th ca-nam"><div class="d"><b>Cả năm ${esc(r.nam)}</b><span>${so(T.soThang)} tháng</span></div><div class="r"><span>Sản lượng</span><b>${so(T.m3)} m³</b></div>
        ${BCN_PHAN.map(p => `<div class="r"><span><i style="background:${p[2]}"></i>${p[0]}</span><b>${tien(T[p[1]])}</b></div>`).join('')}<div class="r tong"><span>Doanh thu</span><b>${tien(tong)}</b></div></div></div></div></div>`;
}
function bcnSVG(r, loai, chon) {
  const W = 340, H = 200, L = 6, R = 6, Tp = 36, B = 24, n = r.thangs.length || 12, slot = (W - L - R) / n, bw = Math.min(20, slot * .64), cao = H - Tp - B;
  const gt = t => t.coSo ? (loai === 'm3' ? t.m3 : t.tong) : null, vs = r.thangs.map(gt), co = vs.filter(v => v !== null);
  const max = Math.max(1, ...co), lon = co.length ? Math.max(...co) : null, nho = co.length > 1 ? Math.min(...co) : null, tb = co.length ? co.reduce((a, v) => a + v, 0) / co.length : 0;
  const nhan = v => loai === 'm3' ? so(v) : (v / 1e6).toFixed(1).replace('.', ',') + ' tr';
  const py = v => Tp + cao - v / max * cao;
  let o = `<svg class="bcn-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Biểu đồ ${loai === 'm3' ? 'sản lượng m³' : 'doanh thu'} từng tháng">
    <defs><linearGradient id="bcnX" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#64b5f6"/><stop offset="1" stop-color="#0b5394"/></linearGradient>
    <linearGradient id="bcnC" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffb74d"/><stop offset="1" stop-color="#ef6c00"/></linearGradient></defs>
    <line x1="${L}" x2="${W - R}" y1="${Tp + cao}" y2="${Tp + cao}" stroke="#c9d3df"/>`;
  if (tb) { const y = py(tb).toFixed(1); o += `<line x1="${L}" x2="${W - R}" y1="${y}" y2="${y}" stroke="#f59e0b" stroke-width="1.2" stroke-dasharray="4 4"/><line x1="${L}" x2="${L + 16}" y1="9" y2="9" stroke="#f59e0b" stroke-width="2" stroke-dasharray="4 3"/><text x="${L + 21}" y="12.5" font-size="10.5" fill="#9a5b00" font-weight="700">Trung bình ${nhan(Math.round(tb))}${loai === 'm3' ? ' m³' : ''}/tháng</text>`; }
  r.thangs.forEach((t, i) => {
    const v = vs[i], cx = L + slot * i + slot / 2, laChon = i === chon;
    o += `<g class="bcn-cot${laChon ? ' on' : ''}" data-i="${i}"><rect x="${(L + slot * i).toFixed(1)}" y="0" width="${slot.toFixed(1)}" height="${H}" fill="transparent"/>`;
    if (v === null) o += `<text x="${cx.toFixed(1)}" y="${Tp + cao - 4}" font-size="11" text-anchor="middle" fill="#c0c8d4">–</text>`;
    else { const y = py(v), h = Math.max(3, Tp + cao - y), mau = v === lon ? 'url(#bcnC)' : 'url(#bcnX)';
      if (laChon) o += `<rect x="${(cx - slot / 2 + 1).toFixed(1)}" y="${(Tp - 4).toFixed(1)}" width="${(slot - 2).toFixed(1)}" height="${(cao + 4).toFixed(1)}" rx="6" fill="#e8f1fb"/>`;
      o += `<rect x="${(cx - bw / 2).toFixed(1)}" y="${(Tp + cao - h).toFixed(1)}" width="${bw.toFixed(1)}" height="${h.toFixed(1)}" rx="4" fill="${mau}" opacity="${v === nho && !laChon ? .55 : 1}"/>`;
      if (laChon) o += `<text x="${Math.min(W - 24, Math.max(24, cx)).toFixed(1)}" y="${(Math.max(12, y - 6)).toFixed(1)}" font-size="11.5" font-weight="800" text-anchor="middle" fill="#083d6e">${nhan(v)}</text>`; }
    o += `<text x="${cx.toFixed(1)}" y="${H - 7}" font-size="10.5" text-anchor="middle" fill="${laChon ? '#083d6e' : '#5b6475'}" font-weight="${laChon ? 800 : 500}">T${Number(String(t.thang).slice(0, 2))}</text></g>`;
  });
  return o + '</svg>';
}
function ganBCNDT(r) {
  let loai = 'm3', chon = -1;
  r.thangs.forEach((t, i) => { if (t.coSo) chon = i; });
  const ve = () => {
    $('bcnSVG').innerHTML = bcnSVG(r, loai, chon);
    const t = r.thangs[chon];
    if (!t) { $('bcnChi').innerHTML = ''; return; }
    let truoc = null; for (let j = chon - 1; j >= 0; j--) if (r.thangs[j].coSo) { truoc = r.thangs[j]; break; }
    const gt = x => loai === 'm3' ? x.m3 : x.tong, ss = t.coSo && truoc && gt(truoc) ? (gt(t) - gt(truoc)) / gt(truoc) * 100 : null;
    $('bcnChi').innerHTML = t.coSo ? `<b>Tháng ${esc(t.thang)}</b><span class="hai"><span>${so(t.m3)} m³</span><span>${tien(t.tong)}</span></span>
      <span class="phu">${so(t.soHo)} hộ${ss !== null ? ` · <em class="${ss >= 0 ? 'tang' : 'giam'}">${ss >= 0 ? '▲' : '▼'} ${Math.abs(ss).toFixed(1).replace('.', ',')}%</em> ${loai === 'm3' ? 'm³' : 'doanh thu'} so với tháng trước` : ''}</span>`
      : `<b>Tháng ${esc(t.thang)}</b><span class="phu">Chưa có số liệu</span>`;
    $$('#bcnSVG .bcn-cot').forEach(g => g.onclick = () => { chon = +g.dataset.i; ve(); });
  };
  $$('#bcnKQ .bcn-chon button').forEach(b => b.onclick = () => { loai = b.dataset.bd; $$('#bcnKQ .bcn-chon button').forEach(x => { x.classList.toggle('on', x === b); x.setAttribute('aria-selected', x === b); }); ve(); });
  $('bcnMoBang').onclick = () => { const mo = $('bcnBang').classList.toggle('an') === false; $('bcnMoBang').setAttribute('aria-expanded', mo); $('bcnMoBang').textContent = mo ? 'Thu gọn bảng từng tháng' : 'Xem bảng từng tháng'; };
  ve();
}
